/* ===== src/js/43-disclose.js ===== */
/* ==========================================================================
   Disclose  (a button that shows or hides the elements it controls)
   --------------------------------------------------------------------------
   The smallest useful disclosure: one button, one or more targets.

     <button data-sg-disclose aria-expanded="false" aria-controls="a b">More levels</button>
     <li id="a" hidden>…</li><li id="b" hidden>…</li>

   Clicking flips aria-expanded and the hidden attribute of every element named in aria-controls
   (a space-separated list). Focus stays on the button: nothing moves, so nothing needs announcing,
   and the state is carried by aria-expanded, which a screen reader reads as "expanded" / "collapsed".
   Keep the button's NAME stable ("More levels", never "Show more" then "Show less"): the state is
   what changes (WAI-ARIA Authoring Practices, Disclosure).

   Event   sg:disclose   bubbles from the button, detail { button, open }
   API     SG.disclose(button [, open])   flip it, or set it with a boolean

   Used by the breadcrumb ("…") and, through SG.chips, the "+N" chip (42-chip.js).
   ========================================================================== */
(function (SG) {
  'use strict';

  function disclose(button, open) {
    var next = typeof open === 'boolean' ? open : button.getAttribute('aria-expanded') !== 'true';
    button.setAttribute('aria-expanded', next ? 'true' : 'false');
    (button.getAttribute('aria-controls') || '').split(/\s+/).forEach(function (id) {
      var target = id && document.getElementById(id);
      if (target) target.hidden = !next;
    });
    button.dispatchEvent(new CustomEvent('sg:disclose', { bubbles: true, detail: { button: button, open: next } }));
    return next;
  }

  document.addEventListener('click', function (e) {
    var b = e.target && e.target.closest && e.target.closest('[data-sg-disclose]');
    if (b) disclose(b);
  });

  SG.disclose = disclose;
})((window.SG = window.SG || {}));
